 static void DepletionRepro(){var s=new Simulation(data,JsonSerializer.Deserialize<State>(File.ReadAllText(Path.Combine(root,"Tools/Expansion/Fixtures/depletion.json")),J));s.S.offlineRemaining=0;s.S.offlineReport=null;var watch=System.Diagnostics.Stopwatch.StartNew();Replay(s,600);Console.WriteLine("Replayed 600s in "+watch.Elapsed.TotalSeconds+"s");Environment.ExitCode=watch.Elapsed.TotalSeconds<10?0:1;}
 static void Replay(Simulation s,double seconds){s.BeginOffline(seconds);while(s.S.offlineRemaining>0)s.ProcessOffline(32768);}
 static void DiscoveryTests(){
  var depletion=new Simulation(data,JsonSerializer.Deserialize<State>(File.ReadAllText(Path.Combine(root,"Tools/Expansion/Fixtures/depletion.json")),J));var depletionWatch=System.Diagnostics.Stopwatch.StartNew();double began=depletion.S.time;Replay(depletion,600);Check("parallel floating-point dust advances ten minutes without event storm",depletionWatch.Elapsed.TotalSeconds<10&&Math.Abs(depletion.S.time-began-600)<.01&&Accounted(depletion));
