  var old=Mature();old.S.discovery=null;var migrated=new Simulation(data,Clone(old.S));Check("2.6 save gains inert discovery state without currency change",migrated.Discover.modules.All(x=>x==0)&&migrated.Discover.goals.Count==0&&migrated.S.resources[0].Value==BigDouble.Parse("1e18"));
  var bad=Clone(migrated.S);bad.discovery.modules=new[]{4,0,0};bool rejected=false;try{new Simulation(data,bad);}catch(ArgumentException){rejected=true;}Check("malformed module save rejected",rejected);
