  var g=Mature();g.Meta.historicResets[0]=g.Meta.historicResets[1]=g.Meta.historicResets[2]=1;g.ConfigureDevelopmentPlan("Energy");g.S.automation.repeatPrestige[0]=true;
  Check("goal queue rejects invalid amount and unknown action",!g.QueueGoal(new GoalOrder{kind=1,amount=new Number(0)})&&!g.QueueGoal(new GoalOrder{after="unknown"}));
  Check("stock goal enables and holds automatic resets",g.QueueGoal(new GoalOrder{kind=1,resource=0,amount=new Number(BigDouble.Parse("1e22")),after="Resume"})&&g.EnableGoals());
