  g.SaveOperations(0,"Goal preset");g.ClearGoals();Check("operations profile restores goal intent",g.ApplyOperations(0)&&g.CurrentGoal!=null&&g.CurrentGoal.amount.Value==BigDouble.Parse("1e22"));
  g.CurrentGoal.amount=new Number(BigDouble.Parse("1e23"));Check("goal profile has no shared mutable order",g.Evolution.operations[0].goals[0].amount.Value==BigDouble.Parse("1e22"));
