  Check("completed savings goal stops automatic spend and reset",stop.Discover.goalIndex==1&&!stop.Discover.goalsEnabled&&stop.Evolution.developmentPlan==""&&!stop.S.automation.buy&&stop.S.reserves[0].Value>0);
  var constructionWatch=System.Diagnostics.Stopwatch.StartNew();var construction=Mature();construction.Meta.megas[1].building=true;construction.Meta.megas[1].work=construction.MegaWork(1)-1;construction.QueueGoal(new GoalOrder{project=1,level=1,after="Time"});construction.EnableGoals();Replay(construction,61);Check("construction goal switches plan after actual completion",construction.Meta.megas[1].level==1&&construction.Evolution.developmentPlan=="Time"&&construction.Discover.goalIndex==1);Check("large flow at construction reserve resolves without microstep storm",constructionWatch.Elapsed.TotalSeconds<10&&construction.S.time>60.99);
  var reserveGoal=Mature();reserveGoal.QueueGoal(new GoalOrder{kind=1,resource=0,amount=new Number(BigDouble.Parse("1e22")),after="Resume"});reserveGoal.EnableGoals();Check("construction cannot consume the active stock goal",!reserveGoal.StartMega(0));reserveGoal.ClearGoals();reserveGoal.CreateUniverse(1);reserveGoal.QueueGoal(new GoalOrder{kind=1,resource=0,amount=new Number(BigDouble.Parse("1e22")),after="Resume"});reserveGoal.EnableGoals();reserveGoal.ScheduleTransfer(0,1,0);Replay(reserveGoal,3600);Check("network exports protect goal stock",reserveGoal.Meta.completedTransfers==0);
  var closed=Mature();closed.EnterChallenge(1);closed.S.owned[4]=5;closed.S.links[0]=1;var unlinked=new Simulation(data,Clone(closed.S));unlinked.S.links[0]=-1;Check("closed challenge ignores existing resonance gains and penalties",Enumerable.Range(0,12).All(r=>Near(closed.Rate(r),unlinked.Rate(r))));
