  var worlds=Mature();worlds.CreateUniverse(1);worlds.CreateUniverse(2);worlds.SetUniverseRole(1,1);var w=worlds.Universe(1);w.S.automation.buy=false;var raw=w.Gross(0);worlds.SetUniverseRole(1,0);Check("supplier role affects parallel production",Near(raw,worlds.Universe(1).Gross(0)*1.12));
  worlds.SetUniverseRole(1,3);worlds.ScheduleTransfer(1,0,0);worlds.Universe(1).S.resources[0]=new BigDouble(10000);worlds.Meta.megas[0].building=true;var without=worlds.MegaSeconds(0);Replay(worlds,3600);Check("construction support requires an actual delivery",worlds.Meta.universes[0].supportUntil>worlds.S.time&&worlds.Meta.completedTransfers>0);worlds.Meta.transfers[0].enabled=false;Replay(worlds,3601);Check("construction support expires without recurring deliveries",worlds.Meta.universes[0].supportUntil<=worlds.S.time);
  for(int c=0;c<12;c++){var s=Mature();Check("challenge constraint applies "+c,s.EnterChallenge(c)&&s.Constraint==1+c%3);if(c%3==0){s.S.resources[0]=BigDouble.Parse("1e18");s.Buy(0,1000);Check("challenge process cap enforced "+c,s.S.owned[0]==25);}if(c%3==1)Check("closed challenge disallows links and voyages "+c,!s.Link(0,1)&&!s.StartVoyage(0));s.ExitChallenge();Check("challenge review retained "+c,s.Discover.challengeReview.Contains(data.challenges[c].name));}
