  var source=Mature();source.Meta.megas[0].level=2;source.SelectModule(0,2);source.QueueGoal(new GoalOrder{kind=1,amount=new Number(BigDouble.Parse("1e22")),after="Resume"});source.EnableGoals();var json=JsonSerializer.Serialize(source.S,J);var experiment=new PlanExperiment(data,Clone(source.S),1d/60);while(!experiment.Done)experiment.Step(257);var exact=new Simulation(data,Clone(source.S));Replay(exact,60);Check("plan laboratory matches literal replay",SameEconomy(experiment.simulation,exact));Check("laboratory cannot mutate original or grant real rewards",json==JsonSerializer.Serialize(source.S,J)&&experiment.Done);
  for(int i=1;i<=3;i++){var a=Simulation.ScenarioState(i,17);var b=Simulation.ScenarioState(i,17);Check("scenario seed is repeatable and separate "+i,JsonSerializer.Serialize(a,J)==JsonSerializer.Serialize(b,J)&&a.discovery.scenario==i&&a.discovery.seed==17);var s=new Simulation(data,a);s.S.lifetime[3]=BigDouble.Pow10(8);Replay(s,60);Check("scenario has a measured finish "+i,s.Discover.scenarioComplete&&s.Discover.scenarioFinished==60);}
  for(int i=0;i<300;i++)source.Chronicle("scenario-"+i,"Completed optional scenario",true);Check("scenario chronicles cannot overflow save limits",source.Discover.firsts.Count==256&&new Simulation(data,Clone(source.S))!=null);
  for(int i=0;i<200;i++)source.Chronicle("bounded",i.ToString());Check("chronicle memory bounded and reloadable",source.Discover.chronicle.Count==160&&new Simulation(data,Clone(source.S)).Discover.chronicle.Count==160);
 }
 static void DiscoveryAudit(){
  var seed=Mature();foreach(var m in seed.Meta.megas){m.level=4;m.building=true;m.work=10;}seed.S.automation.buy=true;seed.Meta.autoResearch=true;seed.S.automation.expeditions=true;seed.SelectModule(0,2);seed.SelectModule(1,3);seed.SelectModule(2,2);seed.CreateUniverse(1);seed.CreateUniverse(2);seed.SetUniverseRole(1,3);seed.SetUniverseRole(2,1);seed.ScheduleTransfer(1,0,0);seed.ScheduleTransfer(2,1,0);seed.QueueGoal(new GoalOrder{project=1,level=5,after="Save"});seed.EnableGoals();
  var a=new Simulation(data,Clone(seed.S));var b=new Simulation(data,Clone(seed.S));var c=new Simulation(data,Clone(seed.S));var watch=System.Diagnostics.Stopwatch.StartNew();
  Replay(a,21600);for(int n=0;n<1296000;n++)b.AdvanceTick();c.BeginOffline(21600);c.ProcessOffline(7919);c=new Simulation(data,Clone(c.S));while(c.S.offlineRemaining>0)c.ProcessOffline(4093);
  Check("discovery six-hour online and offline economy",SameEconomy(a,b));Check("discovery six-hour interrupted economy",SameEconomy(a,c));Check("discovery six-hour automation decisions",a.Discover.goalIndex==c.Discover.goalIndex&&a.Discover.signals.SequenceEqual(c.Discover.signals)&&a.Discover.modules.SequenceEqual(c.Discover.modules));Check("discovery six-hour report conservation",Accounted(a)&&a.S.offlineReport.fixedTicks==1296000);
  Directory.CreateDirectory(Path.Combine(root,"Logs/Discovery"));File.WriteAllText(Path.Combine(root,"Logs/Discovery/tick-audit.json"),JsonSerializer.Serialize(new{pass,fail,ticks=1296000,seconds=watch.Elapsed.TotalSeconds,transfers=a.Meta.completedTransfers,signals=a.Discover.signals,goal=a.Discover.goalStatus},J));Environment.ExitCode=fail==0?0:1;
 }
